import logging
from abc import ABC, abstractmethod
from datetime import datetime, timedelta, timezone
from typing import Optional, Type

import requests
from requests.auth import HTTPBasicAuth
from .exceptions import AuthenticationError

logger = logging.getLogger(__name__)


class GraylogApi(ABC):
    """Abstract base class for Graylog API clients."""

    @abstractmethod
    def __init__(self, base_url, api_token, username, password, default_timeout):
        raise NotImplementedError()

    @abstractmethod
    def query_messages(
        self,
        query: str,
        range_from: int,
        range_seconds: int,
        timeout: Optional[float] = None,
    ):
        raise NotImplementedError()


class GraylogLegacyApi(GraylogApi):
    """
    Legacy Graylog API client for Graylog version 3.x.

    Either `api_token` or `username` and `password` must be provided.
    If both values are provided then `api_token` takes precedence
    over `username` and `password`

    :param str base_url: Graylog server URL (e.g., ``"http://graylog.example.com:9000"``)
    :param str api_token: API token for authentication.
    :param str username: Username for credentials-based authentication.
        Required when API token isn't provided.
    :param str password: Password for credentials-based authentication.
        Required when API token isn't provided.
    :param float | None default_timeout: Default timeout for API requests in seconds.
    """

    def __init__(self, base_url, api_token="", username="", password="", default_timeout=30.0) -> None:
        self.base_url = base_url.rstrip("/")
        self.auth = self._get_auth_params(api_token, username, password)
        self.default_timeout = default_timeout

    def _get_auth_params(self, api_token, username, password) -> HTTPBasicAuth:
        if api_token:
            return HTTPBasicAuth(api_token, "token")
        if username and password:
            return HTTPBasicAuth(username, password)
        raise AuthenticationError(
            "Missing authentication parameters. Provide either 'api_token' or both 'username' and 'password'"
        )

    def query_messages(
        self,
        query: str,
        range_from: int = 0,
        range_seconds: int = 300,
        fields: list[str] = [],
        timeout: Optional[float] = None,
    ) -> list[dict]:
        """
        Query messages from Graylog server based on the provided query and time range.
        Additionally filters the returned fields based on the `fields` parameter.
        If `fields` is empty, all fields are returned.

        :param str query: Graylog search query string.
        :param int range_from: Time offset in whole seconds from the current time to
            start of the search.
        :param int range_seconds: Duration in whole seconds for the search range.
        :param list[str] fields: List of fields to include in the response. If empty,
            all fields are included.
        :param float timeout: Timeout for the API request in seconds. If None, uses
            default timeout.
        :return: List of messages matching the query within the specified time range.
        :rtype: list[dict]
        """
        if timeout is None:
            timeout = self.default_timeout

        url = self.base_url + "/api/search/universal/relative"

        logging.debug("Querying %s messages with query: %s", url, query)

        t_end_iso = (
            (datetime.now(timezone.utc) - timedelta(seconds=range_from))
            .isoformat(timespec="milliseconds")
            .replace("+00:00", "Z")
        )
        t_from_iso = (
            (datetime.now(timezone.utc) - timedelta(seconds=range_seconds + range_from))
            .isoformat(timespec="milliseconds")
            .replace("+00:00", "Z")
        )
        limit = 500
        offset = 0

        headers = {"Accept": "application/json"}
        params = {
            "query": query,
            "from": t_from_iso,
            "to": t_end_iso,
            "range": range_seconds,
            "limit": limit,
            "sort": "timestamp:desc",
            "decorate": "true",
        }

        if fields:
            params["fields"] = ",".join(fields)

        messages = []

        while True:
            resp = requests.get(
                url,
                headers=headers,
                params=params | {"offset": offset},
                auth=self.auth,
                timeout=timeout,
            )
            resp.raise_for_status()
            data = resp.json()

            batch = data["messages"]
            if not batch:
                break
            messages.extend(batch)

            offset += limit

            logging.debug("Fetched %d messages, total %d", len(batch), len(messages))

            if len(messages) >= 10000:
                logging.warning("Reached maximum message limit of 10000, stopping fetch.")
                break

        return messages


def get_version(version: str) -> Type:
    """
    Get the Graylog API client class for the specified version.

    **Note: Currently, only 3.3 version of Graylog API is supported.**
    """
    if version not in VERSION:
        supported = ", ".join(VERSION.keys())
        raise ValueError(f"Unsupported Graylog version: {version}. Supported versions: {supported}")
    return VERSION[version]


VERSION: dict[str, Type] = {
    "3.3": GraylogLegacyApi,
}
